CREATE TABLE widths (
    id INTEGER PRIMARY KEY,
    tiny TINYINT NOT NULL,
    small SMALLINT NOT NULL,
    regular INTEGER NOT NULL,
    big BIGINT NOT NULL,
    utiny UTINYINT NOT NULL,
    usmall USMALLINT NOT NULL,
    uregular UINTEGER NOT NULL,
    ubig UBIGINT NOT NULL,
    huge HUGEINT,
    uhuge UHUGEINT
);
